"use client";
import "./n-progress.css"
import { AppProgressBar as ProgressBar } from "next-nprogress-bar";

export default function Nprogress() {
  return (
    <ProgressBar
      options={{ showSpinner: false }}
      shallowRouting
    />
  );
}

.nprogress {
    pointer-events: none;
    z-index: 99999;
}

.nprogress .bar {
    background: #000012d3;
    position: fixed;
    z-index: 99999;
    top: 0;
    left: 0;
    width: 100%;
    height: 4px;
}
